insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', 'N5', 'A は B です', 'Câu khẳng định/phủ định/nghi vấn: A là B', 'は = chủ ngữ, です/ではありません/ですか = 3 dạng của "là"', NULL, NULL, 'lịch sự (thể です/ます)', NULL, NULL, '{}', NULL, 33, 'A は B です', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('dfbf0679-9db0-4a0b-bade-632a8594c013', 'N5', 'N も', 'Trợ từ も: Cũng...', 'も thay chỗ は/が khi chủ ngữ mới cũng giống chủ ngữ trước', 'N + も (thay cho は/が)', 'Dùng khi chủ ngữ mới cũng có cùng tính chất/hành động như chủ ngữ đã nêu trước đó', NULL, NULL, 'Không dùng cả は và も cùng lúc trên 1 danh từ (Nはも ✗).', '{}', NULL, 33, 'N も', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('98800b21-96eb-4682-828b-8db11d879000', 'N5', 'これ／それ／あれ', 'Đây là／Đó là／Kia là (đại từ chỉ thị sự vật, đứng độc lập)', 'これ gần người nói, それ gần người nghe, あれ xa cả hai', 'これ/それ/あれ + は + N です', 'Dùng độc lập làm chủ ngữ khi chỉ vào 1 vật, KHÔNG đứng trực tiếp trước danh từ', NULL, NULL, 'Không dùng これ/それ/あれ trực tiếp trước danh từ (これ本 ✗) — phải dùng この/その/あの + danh từ (この本 ✓).', '{"この／その／あの + N"}', NULL, 33, 'これ／それ／あれ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('026071bb-2c28-435b-816f-746c37da691f', 'N5', 'この／その／あの + N', 'Danh từ + Này／Đó／Kia (đại từ chỉ định đứng trước danh từ)', 'この/その/あの không bao giờ đứng một mình, luôn kèm danh từ', 'この/その/あの + N (bắt buộc có danh từ theo sau)', 'Chỉ định 1 vật cụ thể đi kèm danh từ ngay sau nó', NULL, NULL, 'この/その/あの không thể đứng một mình làm chủ ngữ như これ/それ/あれ.', '{"これ／それ／あれ"}', NULL, 33, 'この／その／あの + N', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f5dcc24f-98aa-4fe4-9715-9a5340634c1d', 'N5', 'N1 の N2', 'Trợ từ の: ①Của (sở hữu), ②Chỉ nội dung/chủ đề của danh từ đứng sau の', 'の nối 2 danh từ — N1 luôn đứng trước, bổ nghĩa cho N2', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 33, 'N1 の N2', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7b0fb54a-a3e2-4f60-acc9-737f197ee64e', 'N5', 'ここ／そこ／あそこ・こちら／そちら／あちら', 'Giới thiệu về địa điểm: Ở đây／Ở đó／Ở kia', 'こちら nhóm lịch sự hơn ここ nhóm thông thường, cùng nghĩa', 'ここ/そこ/あそこ (thông thường) hoặc こちら/そちら/あちら (lịch sự hơn) + は + N です', 'Giới thiệu 1 địa điểm là gì', 'こちら/そちら/あちら lịch sự hơn ここ/そこ/あそこ, hay dùng khi nói với khách/người lớn tuổi', NULL, NULL, '{}', NULL, 33, 'ここ／そこ／あそこ・こちら／そちら／あちら', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('b01bb0c7-ca5b-4bd6-934a-7c59d9e3646b', 'N5', 'N は どこ／どちらですか', 'Hỏi ai／cái gì／con gì ở đâu', 'どちら lịch sự hơn どこ, cùng nghĩa hỏi vị trí', '(Người/Động vật/Đồ vật) + は + どこ／どちら + ですか', 'Hỏi vị trí của người/vật/động vật đã nêu', NULL, 'どちら lịch sự hơn どこ.', NULL, '{}', NULL, 33, 'N は どこ／どちらですか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('629dfc1d-58a2-424d-be37-dfa8351e5508', 'N5', '学校／お国／会社 は どこ／どちらですか', 'Hỏi về trường học／quốc tịch／công ty', 'Dùng cho 3 chủ đề: nơi học, quốc gia, công ty', 'お国/学校/会社 + は + どこ/どちら + ですか', 'Hỏi quốc tịch, nơi học, hoặc công ty của ai đó', NULL, 'Lưu ý 1: Khi muốn hỏi về công ty nào đó làm về lĩnh vực gì, sản xuất sản phẩm gì: N1はなん＋の＋会社ですか？(N1: tên công ty) → N2の会社です。(N2: tên sản phẩm, lĩnh vực)
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cbc3d331-13ca-455d-848e-3aaf45632a6d', 'N5', 'N は いくらですか', 'Hỏi giá: ~ bao nhiêu tiền', 'いくら = bao nhiêu (tiền)', 'N(đồ vật) + は + いくら + ですか', 'Hỏi giá tiền của 1 đồ vật', NULL, NULL, NULL, '{}', NULL, 34, 'N は いくらですか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('46b6594c-6fb4-43c6-8897-49ab5d703528', 'N5', 'Tính từ đuôi い (Aい)', 'Tính từ có đuôi tận cùng là い', 'Aい → phủ định: bỏ い, thêm くない', 'Vị ngữ: N は Aい です。／Bổ nghĩa danh từ: Aい + N。／Phủ định: Aい → Aくないです。', 'Miêu tả đặc điểm/tính chất, đứng làm vị ngữ hoặc bổ nghĩa trực tiếp cho danh từ theo sau', NULL, 'あまり + thể phủ định = không...lắm/không...mấy. とても／めっちゃ／ちょう／すげえ = rất (mức độ mạnh).', 'Phủ định của tính từ đuôi い là bỏ い cuối rồi thêm くない (おいしい→おいしくない), KHÔNG thêm じゃありません như tính từ đuôi な.', '{"Tính từ đuôi な (Aな)"}', NULL, 37, 'Tính từ đuôi い (Aい)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a7c45010-b0a8-4e13-9361-31768e4a7bd9', 'N5', 'Tính từ đuôi な (Aな)', 'Tính từ có đuôi tận cùng là な', 'Aな → BỎ な khi làm vị ngữ, GIỮ な khi đứng trước danh từ', 'Vị ngữ: N は A です。(bỏ な)／Bổ nghĩa danh từ: Aな + N。(giữ な)／Phủ định: A → Aじゃありません。', 'Miêu tả đặc điểm/tính chất; khi làm vị ngữ cuối câu KHÔNG có な, khi bổ nghĩa trực tiếp cho danh từ PHẢI có な', NULL, 'あまり + thể phủ định = không...lắm. とても／めっちゃ／ちょう／すげえ = rất.', 'Dễ nhầm giữ な khi làm vị ngữ (親切なです ✗, phải là 親切です ✓); ngược lại hay quên thêm な khi bổ nghĩa danh từ (親切人 ✗, phải là 親切な人 ✓).', '{"Tính từ đuôi い (Aい)"}', NULL, 37, 'Tính từ đuôi な (Aな)', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('cea3a65e-c45d-4e84-95d0-c221a75a6a9a', '4899cadb-d2c9-447b-968f-b4fa203475fc', 1, 'Câu khẳng định: A là B', 'N1 は N2 です', 'Khẳng định A chính là B', NULL, 33, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('4d988444-7f77-48c8-8954-d5a998235ab6', '4899cadb-d2c9-447b-968f-b4fa203475fc', 2, 'Câu phủ định: A không phải là B', 'N1 は N2 ではありません／じゃありません', 'Phủ định A không phải là B', NULL, 33, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('1433309a-c0ea-4721-adde-60a8799d9931', '4899cadb-d2c9-447b-968f-b4fa203475fc', 3, 'Câu nghi vấn: A là B phải không?', 'N1 は N2 ですか', 'Hỏi xác nhận A có phải là B không', 'Trả lời: はい (Vâng)／いいえ (Không).', 33, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('5cfffe2a-2a65-495f-94a3-57b5ef1ab372', 'f5dcc24f-98aa-4fe4-9715-9a5340634c1d', 1, 'Sở hữu: N1 の N2 = N2 của N1', 'N1(người/vật sở hữu) + の + N2(vật được sở hữu)', 'Nối 2 danh từ để chỉ quan hệ sở hữu', NULL, 33, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('c89b0dba-477e-4e7a-8e88-464ed287a71b', 'f5dcc24f-98aa-4fe4-9715-9a5340634c1d', 2, 'Chỉ nội dung/chủ đề của danh từ đứng sau の', 'N1(nội dung/chủ đề) + の + N2(danh từ chính)', 'N1 mô tả nội dung/lĩnh vực của N2', NULL, 33, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', 'cea3a65e-c45d-4e84-95d0-c221a75a6a9a', 1, 'standard', 'わたしはベトナムじんです。', 'Tôi là người Việt Nam.', 'わたしは＿＿＿です。', 'ベトナムじん', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', 'cea3a65e-c45d-4e84-95d0-c221a75a6a9a', 2, 'daily', 'わたしはがくせいです。', 'Tôi là học sinh.', 'わたしは＿＿＿です。', 'がくせい', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', 'cea3a65e-c45d-4e84-95d0-c221a75a6a9a', 3, 'daily', 'チャンさんはせんせいです。', 'Chị Trang là giáo viên.', 'チャンさんは＿＿＿です。', 'せんせい', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', '4d988444-7f77-48c8-8954-d5a998235ab6', 1, 'standard', 'わたしはベトナムじんではありません。', 'Tôi không phải người Việt Nam.', 'わたしはベトナムじん＿＿＿。', 'ではありません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', '4d988444-7f77-48c8-8954-d5a998235ab6', 2, 'standard', 'あのひとはかんこくじんじゃありません。', 'Người kia không phải là người Hàn Quốc.', 'あのひとはかんこくじん＿＿＿。', 'じゃありません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', '4d988444-7f77-48c8-8954-d5a998235ab6', 3, 'daily', 'わたしはにほんじんじゃありません。', 'Tôi không phải người Nhật.', 'わたしはにほんじん＿＿＿。', 'じゃありません', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', '1433309a-c0ea-4721-adde-60a8799d9931', 1, 'standard', 'ミンさんはベトナムじんですか。', 'Anh Minh là người Việt Nam phải không?', 'ミンさんはベトナムじん＿＿＿。', 'ですか', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', '1433309a-c0ea-4721-adde-60a8799d9931', 2, 'standard', 'はい、ベトナムじんです。', 'Vâng, tôi là người Việt Nam.', 'はい、ベトナムじん＿＿＿。', 'です', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4899cadb-d2c9-447b-968f-b4fa203475fc', '1433309a-c0ea-4721-adde-60a8799d9931', 3, 'standard', 'いいえ、ベトナムじんじゃありません。', 'Không, tôi không phải người Việt Nam.', 'いいえ、ベトナムじん＿＿＿。', 'じゃありません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('dfbf0679-9db0-4a0b-bade-632a8594c013', NULL, 1, 'standard', 'わたしはがくせいです。チャンさんもがくせいです。', 'Tôi là học sinh. Trang cũng là học sinh.', 'チャンさん＿＿＿がくせいです。', 'も', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('dfbf0679-9db0-4a0b-bade-632a8594c013', NULL, 2, 'daily', 'わたしはにほんごをべんきょうします。ミンさんもにほんごをべんきょうします。', 'Tôi học tiếng Nhật. Anh Minh cũng học tiếng Nhật.', 'ミンさん＿＿＿にほんごをべんきょうします。', 'も', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('dfbf0679-9db0-4a0b-bade-632a8594c013', NULL, 3, 'daily', 'これはほんです。それもほんです。', 'Đây là sách. Đó cũng là sách.', 'それ＿＿＿ほんです。', 'も', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('98800b21-96eb-4682-828b-8db11d879000', NULL, 1, 'standard', 'それはけいたいです。', 'Đó là điện thoại di động.', '＿＿＿はけいたいです。', 'それ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('98800b21-96eb-4682-828b-8db11d879000', NULL, 2, 'standard', 'これはなんですか。', 'Đây là cái gì?', '＿＿＿はなんですか。', 'これ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('98800b21-96eb-4682-828b-8db11d879000', NULL, 3, 'daily', 'あれはとりです。', 'Kia là con chim.', '＿＿＿はとりです。', 'あれ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('026071bb-2c28-435b-816f-746c37da691f', NULL, 1, 'standard', 'このけいたいはあたらしいです。', 'Cái điện thoại di động này mới.', '＿＿＿けいたいはあたらしいです。', 'この', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('026071bb-2c28-435b-816f-746c37da691f', NULL, 2, 'standard', 'そのほんはおもしろいです。', 'Quyển sách đó thú vị.', '＿＿＿ほんはおもしろいです。', 'その', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('026071bb-2c28-435b-816f-746c37da691f', NULL, 3, 'standard', 'あのくるまはたかいです。', 'Chiếc xe hơi kia đắt.', '＿＿＿くるまはたかいです。', 'あの', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f5dcc24f-98aa-4fe4-9715-9a5340634c1d', '5cfffe2a-2a65-495f-94a3-57b5ef1ab372', 1, 'standard', 'あれはだれのかばんですか。', 'Kia là cặp của ai vậy?', 'あれはだれ＿＿＿かばんですか。', 'の', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f5dcc24f-98aa-4fe4-9715-9a5340634c1d', '5cfffe2a-2a65-495f-94a3-57b5ef1ab372', 2, 'standard', 'わたしのかばんです。', 'Là cặp của tôi.', 'わたし＿＿＿かばんです。', 'の', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f5dcc24f-98aa-4fe4-9715-9a5340634c1d', '5cfffe2a-2a65-495f-94a3-57b5ef1ab372', 3, 'daily', 'これはミンさんのほんです。', 'Đây là sách của anh Minh.', 'これはミンさん＿＿＿ほんです。', 'の', 'generated');
